// TH18 v1.00a st03mbs.ecl.txt:6-133 MBoss / MBoss1.
// Source entry: MBoss at (-192,-64), 100-frame QUAD_OUT move to (0,128), wait38,
// dialog omitted, then MBoss1 (wait60 + charge effect + wait80) starts firing.
// Source slot-1 timeout 1440; the 120-frame shell buffer sits before the real boss
// spawn, so target TIME_LIMIT = 120 + 1440.
const TIME_LIMIT: int = 1560;
const SOURCE_LIMIT: int = 1440;
const TH18_SHARD: int = 512;

// MBoss1_at EX program after the per-bullet writes (st03mbs.ecl.txt:94-126):
//   0 ANIM a=1           -> retreat kept below as sh_dist(-12.8)
//   1 OFFSCREEN a=200    -> offscreen_keep(200)
//   2 VELTIME 60, r=0.03, s=-1000000  (current angle), 3.2 -> 0.03
//   3 VELTIME 30, r=2.0,  s=1000000   (player + %E),     0.03 -> 2.0
//   4 VELTIME 30, r=0.03, s=-1000000  (current angle),   2.0 -> 0.03
//   5 VELTIME 30, r=rank speed, s=1000000 (%F + 5deg*RANDF2), 0.03 -> r
// Record 3 overwrites the initial 10-frame WAIT; records 3 and 5 are rewritten
// per bullet by etExSet2 before etOn. All four VELTIME effects are serial.
// VELTIME saves its direction on entry and changes the logical scalar speed by
// (target-current)/a each tick; POLAR set_accel keeps that scalar exactly (the
// later stages read the logical scalar, not the vector length).  @N is a
// post-op delay: "@60 set_accel(...)" runs 60 ticks of that acceleration.
xformdef MB_SHARD(vel: fx, base: angle, base2: angle) {
    offscreen_keep(200);
    // record 2: along the spawn angle
    @60 set_accel((0.03fx - 3.2fx) / 60fx);
    stop_fx();
    // record 3: toward the player plus this ring's %E, sampled on entry
    set_angle(at_effect(aim_player() + base));
    set_speed(0.03fx);
    @30 set_accel((2.0fx - 0.03fx) / 30fx);
    stop_fx();
    // record 4: along the angle reached above
    @30 set_accel((0.03fx - 2.0fx) / 30fx);
    stop_fx();
    // record 5: toward the player plus %F; the source draws %RANDF2 once per
    // bullet in the inner loop, so at_spawn keeps that per-bullet draw.
    set_angle(at_effect(aim_player() + base2));
    turn(at_spawn((((rand(65536) - 32768) * 910) / 32768) as angle)); // 5deg * RANDF2
    @30 set_accel((vel - 0.03fx) / 30fx);
    stop_fx();
}

// moveRand(60,4,0.7) under moveLimit(0,128,280,32): actual x +/-140,
// y 112..144; the direction-selection inner box is center +/- width/4 or
// height/4, i.e. x +/-70 and y 120..136.  Native speed slot inherits mode 0,
// i.e. 0.7*(1-k/60) for k=1..60.  The helper pre-arms the next source
// movement tick because target phase5 moves after ECL.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx * ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 144fx { ny = 144fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Source 405b90 = signed unit random * pi.  Width 280 => central x +/-70.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 120fx {
        if a < 0 { a = -a; }
    } else if $self_y > 136fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// MBoss1_at(A): B=16 Easy / 32 others, C=I0, initial speed 3.2,
// C bullets per ring, B rings per call.  D and E are independent RANDRAD
// draws; F=E+A and both E and F advance by 2*pi/B per ring.  Each ring's
// sh_fire reproduces the source inner C-bullet loop (full ring at base D).
sub mb_at(a: angle, i0: int) {
    var rank: int = global(GVAR_RANK);
    var b: int = 32;
    if rank == 0 { b = 16; }
    var c: int = i0;
    var vel: fx = 2.0fx;
    if rank == 2 { vel = 2.4fx; }
    if rank == 3 { vel = 2.8fx; }
    var d: int = rand(65536);
    var e: int = rand(65536);
    var step_b: int = 65536 / b;
    var step_d: int = step_b / c;
    sh_reset(0);
    sh_sprite(0, TH18_SHARD, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, c, 1);
    sh_speed(0, 3.2fx, 0fx);
    sh_dist(0, -12.8fx); // ANIM a=1: position -= 4*initial velocity
    for j in 0..b {
        // Source increments E/F by 2*pi/B and D by (2*pi/B)/C before each ring.
        e = e + step_b;
        d = d + step_d;
        sh_angle(0, d as angle, 0deg);
        // F=E+A holds every ring; record 3 uses E, record 5 uses F.
        sh_xform(0, MB_SHARD(vel, e as angle, (e + (a as int)) as angle));
        sh_fire(0);
    }
}

async sub mb1_boss() {
    set_invuln(65535);
    set_hitbox(20fx);  // source setHitbox(40,40)
    set_hurtbox(24fx); // source setHurtbox(48,48)
    set_self_int(0, 0);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);
    wait(38); // source wait before dialogWait; dialog is omitted
    wait(60); // MBoss1 entry wait
    wait(80); // after EffChargePoint3 (pure effect omitted)
    var rank: int = global(GVAR_RANK);
    var r: int = 120;
    if rank == 2 { r = 90; }
    if rank == 3 { r = 60; }
    var a: angle = 90deg;
    var i0: int = 12;
    mb_at(a, i0);
    a = -a;
    wait(r); // no moveRand active yet
    card_move_rand();
    card_wait(r);
    if i0 < 16 { i0 = i0 + 1; }
    loop {
        mb_at(a, i0);
        a = -a;
        card_wait(r);
        card_move_rand();
        card_wait(r);
        if i0 < 16 { i0 = i0 + 1; }
    }
}

// 120-frame shell buffer, then the real midboss.  The control enemy owns the
// phase timer and has no body; the real enemy keeps the source 20/24 circles.
async sub mb1_wave() {
    wait(120);
    _ = spawn_enemy(-192fx, -64fx, 13000, 0, 0, 0, mb1_boss);
    loop { wait(1); }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, mb1_wave, TIME_LIMIT, 0);
    wait_spell();
    // The real enemy is spawned by the phase pattern and is not its task child;
    // silent-clear it at timeout so the shell envelope ends with the segment.
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, control_main);
    loop { wait(600); }
}
